import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Connectors","description":"","frontmatter":{},"headers":[],"relativePath":"guides/connectors.md","filePath":"guides/connectors.md","lastUpdated":1788855895000}'),i={name:"guides/connectors.md"};function s(r,e,c,h,l,d){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="connectors" tabindex="-1">Connectors <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;Connectors&quot;">​</a></h1><p>Connectors let a bot use third-party services such as GitHub or Notion. You pick a service from the Supermarket catalog, authorize it with OAuth or an API key, and bind it to a bot — from then on the bot can call that service&#39;s tools directly in conversation.</p><p>Behind the scenes, connections are managed by <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a>, a companion service deployed next to Memoh. All credentials (OAuth tokens, API keys) live in Connect-It; Memoh only keeps a binding record — which bot is bound to which connection, what its tool namespace is, and whether it is enabled.</p><hr><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>Connectors are available when the server is configured with a Connect-It endpoint:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect_it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # e.g. &quot;http://connect-it:8421&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # trusted server-to-server token</span></span></code></pre></div><p>Leaving both empty disables the feature. In deployed environments, prefer the matching environment variables (<code>MEMOH_CONNECT_IT_BASE_URL</code>, <code>MEMOH_CONNECT_IT_API_TOKEN</code>).</p><p>The one-click server deployment provisions a co-hosted Connect-It automatically on fresh installs; see <a href="/self-hosted/docker.html#connect-it-connectors">Server Deploy</a>. When Connect-It is not configured, the Supermarket hides the <strong>Connectors</strong> tab and connector operations report that connectors are not configured on this server.</p><hr><h2 id="connect-a-service" tabindex="-1">Connect A Service <a class="header-anchor" href="#connect-a-service" aria-label="Permalink to &quot;Connect A Service&quot;">​</a></h2><ol><li>Open <strong>Supermarket</strong> in the Web UI.</li><li>Stay on the <strong>Connectors</strong> tab — it is the first tab and the default landing tab when connectors are configured.</li><li>Choose a connector and click <strong>Connect</strong>.</li><li>Select the target bot.</li><li>Choose an authentication method — OAuth or API key, depending on what the connector supports.</li><li>For OAuth, complete the authorization popup. If the browser blocks it, allow popups for the page and try again. For API keys, fill in the credential fields.</li><li>The connection appears in the bot&#39;s <strong>Connectors</strong> tab.</li></ol><hr><h2 id="manage-connections" tabindex="-1">Manage Connections <a class="header-anchor" href="#manage-connections" aria-label="Permalink to &quot;Manage Connections&quot;">​</a></h2><p>The bot detail page has a <strong>Connectors</strong> tab listing the bot&#39;s connected services. Each connection shows one of these statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Connected</strong></td><td>Active. The connection&#39;s tools are available to the bot.</td></tr><tr><td><strong>Waiting for authorization</strong></td><td>The connection was created but OAuth was never completed. Finish the authorization or disconnect it.</td></tr><tr><td><strong>Authorization required</strong></td><td>Credentials expired or were revoked. Click <strong>Reauthorize</strong>.</td></tr><tr><td><strong>Authorization failed</strong></td><td>The last authorization attempt did not succeed. Try <strong>Reauthorize</strong> again.</td></tr><tr><td><strong>Unavailable</strong></td><td>The connector is no longer available on the Connect-It side.</td></tr><tr><td><strong>Disabled</strong></td><td>Turned off. The connection&#39;s tools are not offered to the bot.</td></tr></tbody></table><p>From the same tab you can:</p><ul><li><strong>Enable / disable</strong> a connection without removing it.</li><li><strong>Reauthorize</strong> a connection whose credentials went stale.</li><li><strong>Disconnect</strong> a connection — this removes the binding from the bot <strong>and</strong> deletes the stored connection, including its credentials, in Connect-It.</li></ul><p>If you abandon an OAuth authorization halfway, the connection stays in <strong>Waiting for authorization</strong> until you disconnect it.</p><hr><h2 id="how-tools-reach-the-bot" tabindex="-1">How Tools Reach The Bot <a class="header-anchor" href="#how-tools-reach-the-bot" aria-label="Permalink to &quot;How Tools Reach The Bot&quot;">​</a></h2><p>At conversation time, Memoh combines all of the bot&#39;s enabled, active connections into a single aggregated MCP session and offers it to the agent as a tool source. Connector tools appear alongside workspace and MCP tools.</p><p>Each connection gets a <strong>tool namespace</strong> derived from the connector type when it is first bound — <code>github</code> for a GitHub connection, <code>github-2</code> for a second one. The namespace is fixed for the lifetime of the binding: connecting or disconnecting other services never renames an existing connection&#39;s tools.</p><hr><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/guides/supermarket.html">Supermarket</a> — where connectors are discovered and connected.</li><li><a href="/guides/mcp.html">MCP</a> — direct MCP connection management.</li><li><a href="/self-hosted/docker.html#connect-it-connectors">Server Deploy</a> — co-hosted Connect-It provisioning, credentials, and the OAuth callback URL.</li></ul>`,26)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
